def nats(engine, flags):
    cmd = ([engine, "--weights", S15, "--threads", str(THREADS), "--seqlen", str(SEQLEN)]
           + list(flags) + ["--bpb", IDS])
    txt, dt = run(cmd, "bpb")
    m = RE_NATS.search(txt)
    if not m:
        raise SystemExit("could not parse NATS_TOTAL")
    return float(m.group(1)), int(m.group(2)), dt


